export function LimitedOfferCarousel() {
  const [modalOpen, setModalOpen] = useState(false);
  const hoverTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const dismissedDuringHover = useRef(false);

  function clearHoverTimer() {
    if (hoverTimer.current) {
      clearTimeout(hoverTimer.current);
      hoverTimer.current = null;
    }
  }

  function scheduleModal() {
    if (dismissedDuringHover.current || window.matchMedia("(hover: none)").matches) {
      return;
    }

    clearHoverTimer();
    hoverTimer.current = setTimeout(() => setModalOpen(true), 650);
  }

  function leaveCampaign() {
    clearHoverTimer();
    dismissedDuringHover.current = false;
  }

  function closeModal() {
    dismissedDuringHover.current = true;
    setModalOpen(false);
  }

  useEffect(() => {
    function onKeyDown(event: KeyboardEvent) {
      if (event.key === "Escape") {
        closeModal();
      }
    }

    window.addEventListener("keydown", onKeyDown);
    return () => {
      clearHoverTimer();
      window.removeEventListener("keydown", onKeyDown);
    };
  }, []);

  return (
    <>
      <section
        className="relative overflow-hidden bg-[#eee8df] py-12 text-[#171717] md:py-16"
        aria-labelledby="new-arrivals-heading"
        onMouseEnter={scheduleModal}
        onMouseLeave={leaveCampaign}
      >
        <div className="container-luxe">
          <header className="mb-7 flex items-end justify-between gap-5">
            <div>
              <p className="text-[10px] font-semibold uppercase text-[#9f751d]">LIMITED OFFER</p>
              <h2 id="new-arrivals-heading" className="mt-2 text-2xl font-semibold sm:text-3xl">
                New Arrivals
              </h2>
            </div>
            <button
              type="button"
              onClick={() => setModalOpen(true)}
              className="gold-focus inline-flex items-center gap-2 border-b border-black/45 pb-1 text-[10px] font-semibold uppercase transition hover:border-[#9f751d] hover:text-[#9f751d]"
            >
              SHOP THE OFFER
              <ArrowRight className="h-3.5 w-3.5" />
            </button>
          </header>

          <div className="grid grid-cols-2 gap-2 sm:grid-cols-4 md:gap-3">
            {campaignImages.map((image) => (
              <Link
                key={image.src}
                href={image.href}
                className="gold-focus group relative aspect-[3/4] overflow-hidden bg-[#eee8df]"
                aria-label={`Shop ${image.name}`}
              >
                <Image
                  src={image.src}
                  alt={image.alt}
                  fill
                  quality={92}
                  sizes="(min-width: 640px) 25vw, 50vw"
                  className="object-cover object-center transition duration-700 ease-out group-hover:scale-[1.018]"
                />
                <div className="absolute inset-x-0 bottom-0 bg-gradient-to-t from-black/62 to-transparent px-3 pb-3 pt-12 text-white">
                  <p className="text-[9px] font-semibold uppercase">{image.name}</p>
                </div>
              </Link>
            ))}
          </div>
        </div>
      </section>

      {modalOpen ? (
        <div className="fixed inset-0 z-[120] grid place-items-center p-4 sm:p-8">
          <button
            type="button"
            className="absolute inset-0 bg-black/58 backdrop-blur-sm"
            onClick={closeModal}
            aria-label="Close limited offer"
          />
          <section
            role="dialog"
            aria-modal="true"
            aria-labelledby="limited-offer-title"
            className="relative w-full max-w-lg bg-[#f7f3e8] px-6 py-8 text-[#171717] shadow-2xl sm:px-10 sm:py-10"
          >
            <button
              type="button"
              onClick={closeModal}
              className="gold-focus absolute right-4 top-4 grid h-10 w-10 place-items-center border border-black/20 transition hover:border-black hover:bg-black hover:text-white"
              aria-label="Close offer details"
            >
              <X className="h-4 w-4" />
            </button>
            <p className="text-[10px] font-semibold uppercase text-[#a47a25]">LIMITED OFFER</p>
            <h2
              id="limited-offer-title"
              className="mt-4 max-w-md text-3xl font-semibold leading-tight sm:text-4xl"
            >
              Buy Two Outfits And Get 50% Off The Third.
            </h2>
            <p className="mt-5 max-w-md text-sm leading-7 text-black/62">
              Offer repeats on every eligible order with discounts automatically applied before
              payment.
            </p>
            <Link
              href={newArrivalsPromotion.href}
              onClick={closeModal}
              className="gold-focus mt-8 inline-flex min-h-11 items-center justify-center gap-3 bg-black px-5 text-[10px] font-semibold uppercase text-white transition hover:bg-gold hover:text-black"
            >
              SHOP NEW DESIGNS
              <ArrowRight className="h-4 w-4" />
            </Link>
          </section>
        </div>
      ) : null}
    </>
  );
}
